\uc548\ub0b4\ub85c \uc774\ub04c\uae30", "tone": "calm"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\ud559\uc0dd\uc774 \uc2a4\uc2a4\ub85c \uc7a5\uc18c+\ud589\ub3d9 \ubb38\uc7a5\uc744 \ub9d0\ud574 \ubcfc \ub54c, \uc5ec\uc720\ub97c \uc8fc\uba70 \uaca9\ub824\ud558\ub294 \uc5ed\ud560\uc744 \ud558\uae30", "tone": "reassuring"}], "teacherReviewFocus": ["\uc548\ub0b4\ubb38 \uae38\uc774\ub294 1\uc904 \uc7a5\uc18c+1\uc904 \ud589\ub3d9 \uc815\ub3c4\ub85c \ub9e4\uc6b0 \uc9e7\uac8c \uc720\uc9c0\ud558\uae30", "\ubaa8\ub4e0 \uc9c8\ubb38\uacfc \uc9c0\uc2dc\ub294 \ud55c \ubc88\uc5d0 \ud55c \uac00\uc9c0 \uc815\ubcf4\ub9cc \uc694\uad6c\ud558\ub3c4\ub85d \ubb38\uc7a5\uc744 \uc9e7\uac8c \ub098\ub204\uae30", "\uc120\ud0dd\uc9c0\ub294 \ud56d\uc0c1 2\uac1c\ub85c \uc81c\ud55c\ud574 \ubd80\ub2f4\uc744 \uc904\uc774\uae30", "\uc7a5\uc18c \ub2e8\uc5b4\uc640 \ud589\ub3d9 \ubb38\uc7a5\uc744 \uc0c9\uc774\ub098 \uc704\uce58\ub85c \uc790\uc5f0\uc2a4\ub7fd\uac8c \uad6c\ubd84\ub418\ub3c4\ub85d \uad6c\uc870\ud654\ud558\uae30(\uc608: \uc704/\uc544\ub798, \uc67c\ucabd/\uc624\ub978\ucabd)", "\ud559\uc0dd\uc774 \ub530\ub77c \ub9d0\ud558\uae30 \uc88b\uc740 \uc9e7\uc740 \uc608\uc2dc \ubb38\uc7a5\uc744 \ucda9\ubd84\ud788 \ub4e4\uc744 \uc218 \uc788\ub3c4\ub85d \uc624\ub514\uc624 \uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c \ubc18\ubcf5 \uc81c\uacf5\ud558\uae30"], "safetyNotes": ["\ud559\uc0dd\uc758 \uc2e4\uc81c \ud559\uad50 \uc774\ub984, \ud559\uae09, \uc5bc\uad74 \ub4f1 \uac1c\uc778\uc744 \ud2b9\uc815\ud560 \uc218 \uc788\ub294 \uc694\uc18c\ub294 \uc774\ubbf8\uc9c0\uc5d0 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4.", "\uc601\uc5b4 \uc548\ub0b4\ubb38\uc740 \ucd08\ub4f1 \uc218\uc900 \uc5b4\ud718\uc640 \uae0d\uc815\uc801 \ud589\ub3d9 \uc548\ub0b4\ub85c\ub9cc \uad6c\uc131\ud558\uace0, \uc704\ud611\uc801\uc774\uac70\ub098 \ucc98\ubc8c\uc744 \uc554\uc2dc\ud558\ub294 \ud45c\ud604\uc740 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4."], "normalizationNotes": ["\uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130 \ub2e8\uacc4 \ub77c\ubca8/\ud15c\ud50c\ub9bf \uac12\uc744 \uc81c\ud488 \uacc4\uc57d\uc5d0 \ub9de\uac8c \uc790\ub3d9 \uc815\uaddc\ud654\ud588\uc2b5\ub2c8\ub2e4.", "1\ub2e8\uacc4: {''stageRole'': ''concept_intro'', ''studentTitle'': ''\uac1c\ub150 \uc5f4\uae30'', ''templateType'': ''scenario_intro''} -> {''stageRole'': ''concept_intro'', ''studentTitle'': ''\uac1c\ub150 \uc5f4\uae30'', ''templateType'': ''concept_intro''}"]}, "generationPlan": {"unitVersion": "content_generation_units_v1", "scenarioPlan": {"unitId": "scenario", "scenarioSpine": {"scenarioTitle": "\ud559\uad50 \uc548\ub0b4\ud310\uc73c\ub85c \ucc3e\ub294 \uc7a5\uc18c\uc640 \ud574\uc57c \ud560 \uc77c", "anchorSituation": "\ud559\uad50 \ubcf5\ub3c4\uc5d0\uc11c \uc601\uc5b4\ub85c \ub41c \uac04\ub2e8\ud55c \uc548\ub0b4\ud310\uc744 \ubcf4\uace0, \uc5b4\ub514\ub85c \uac00\uc57c \ud558\ub294\uc9c0\uc640 \uadf8\uacf3\uc5d0\uc11c \ubb34\uc5c7\uc744 \ud574\uc57c \ud558\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uc0c1\ud669", "targetSkill": "\uc548\ub0b4\ubb38 \uc18d \uc601\uc5b4 \uc7a5\uc18c \ub2e8\uc5b4\uc640 \ud589\ub3d9 \ub2e8\uc5b4\ub97c \uad6c\ubd84\ud574\uc11c \uc9e7\uac8c \ub9d0\ub85c \ud45c\ud604\ud558\uae30", "keyEvidence": "\ud559\uad50 \ubcf5\ub3c4 \ubcbd\uc5d0 \ubd99\uc740 \uac04\ub2e8\ud55c \uc601\uc5b4 \uc548\ub0b4\ubb38(\uc608: Library \u2013 Be quiet, Gym \u2013 Wear sports shoes)\uacfc \uc548\ub0b4 \ud654\uc0b4\ud45c, \uc544\uc774\ucf58 \uadf8\ub9bc", "studentAction": "\uc548\ub0b4\ubb38\uc744 \ubcf4\uace0 \u2018\uc5b4\ub514(\uc7a5\uc18c)\uc778\uc9c0\u2019\uc640 \u2018\ubb34\uc5c7\uc744 \ud574\uc57c \ud558\ub294\uc9c0\u2019\ub97c \uc9e7\uac8c \uc77d\uac70\ub098 \ub9d0\ub85c \uad6c\ubd84\ud558\uc5ec \ub9d0\ud558\uae30", "emotionalTone": "\ud559\uad50\uc5d0\uc11c \uc2e4\uc81c\ub85c \ubcfc \uc218 \uc788\ub294 \uc7a5\uba74\uc744 \ubc14\ud0d5\uc73c\ub85c, \ucc28\ubd84\ud558\uace0 \uc775\uc219\ud55c \ub290\ub08c\uc774 \ub098\ub3c4\ub85d \uad6c\uc131", "commonMistakeOrImpulse": "\uc548\ub0b4\ubb38 \uc804\uccb4\ub97c \ud55c \ubc88\uc5d0 \uc77d\uc73c\ub824 \ud558\ub2e4\uac00 \ubd80\ub2f4\uc744 \ub290\ub07c\uac70\ub098, \uc7a5\uc18c \ub2e8\uc5b4\uc640 \ud589\ub3d9 \ub2e8\uc5b4\ub97c \uc11e\uc5b4\uc11c \uae30\uc5b5\ud568", "whyThisMatters": "\ud559\uad50\uc5d0\uc11c \uc601\uc5b4\ub85c \ub41c \uc548\ub0b4\ubb38\uc774\ub098 \ud45c\uc9c0\ub97c \ubcf4\uc558\uc744 \ub54c, \ud575\uc2ec \ub2e8\uc11c\uc778 \uc7a5\uc18c\uc640 \ud574\uc57c \ud560 \ud589\ub3d9\uc744 \ube60\ub974\uac8c \uc774\ud574\ud558\uace0 \ub9d0\ub85c \ud655\uc778\ud560 \uc218 \uc788\uc5b4\uc57c \uc2e4\uc81c \uc0c1\ud669\uc5d0\uc11c \ub3c4\uc6c0\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4.", "studentLikelyImpulseOrMisconception": "\uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \ubcf4\uba74 \uae00\uc774 \uae38\uac70\ub098 \ub0af\uc124\uc5b4 \ubcf4\uc5ec\uc11c \ubc14\ub85c \ud3ec\uae30\ud558\ub824 \ud558\uac70\ub098, \ud55c \ub2e8\uc5b4(\uc608: Library)\ub9cc \ubcf4\uace0 \uadf8 \uc548\uc5d0 \uc801\ud78c \ud589\ub3d9 \ubb38\uc7a5\uc740 \ubb34\uc2dc\ud560 \uc218 \uc788\ub2e4.", "stage2FirstSuccess": "\ud55c \uc548\ub0b4\ubb38\uc5d0\uc11c \uc7a5\uc18c \ub2e8\uc5b4\uc640 \ud589\ub3d9 \ub2e8\uc5b4\ub97c \uc774\ubbf8\uc9c0\uc640 \ud568\uaed8 \uc9e7\uac8c \ubcf4\uace0, \u2018\uc774 \uc548\ub0b4\ubb38\uc740 \uc5b4\ub514? \ubb34\uc5c7\uc744 \ud574\uc57c \ud574?\u2019\ub97c \ud55c \ubc88\uc5d0 \ubb3b\uc9c0 \uc54a\uace0 \ub098\ub204\uc5b4 \ud655\uc778\ud558\uac8c \ud55c\ub2e4.", "stage3Transfer": "\ub450 \ubc88\uc9f8 \uc548\ub0b4\ubb38\uc5d0\uc11c \ube44\uc2b7\ud55c \ud615\uc2dd\uc73c\ub85c, \ube44\uc5b4 \uc788\ub294 \ubd80\ubd84(\uc7a5\uc18c \ub610\ub294 \ud589\ub3d9)\uc744 \uace8\ub77c \ub123\uc73c\uba74\uc11c \uc7a5\uc18c-\ud589\ub3d9 \uc9dd\uc744 \ub2e4\uc2dc \ud55c \ubc88 \uad6c\ubd84\ud574 \ubcf8\ub2e4.", "stage4Reuse": "\uc2e4\uc81c \ud559\uad50\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \uc548\ub0b4\ubb38 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub824, \uc2a4\uc2a4\ub85c \uc9e7\uc740 \uc548\ub0b4\ubb38(\uc7a5\uc18c+\ud574\uc57c \ud560 \ud589\ub3d9)\uc744 \ub9d0\ub85c \ub9cc\ub4e4\uc5b4 \ubcf4\uac70\ub098, \uc81c\uc2dc\ub41c \uc548\ub0b4\ubb38\uc744 \uc18c\ub9ac \ub0b4\uc5b4 \uc77d\uc73c\uba70 \uc5f0\uc2b5\ud55c\ub2e4."}, "sessionGoal": "\ud559\uad50 \uc548\ub0b4\ubb38\uc5d0\uc11c \uc601\uc5b4 \uc7a5\uc18c \ub2e8\uc5b4\uc640 \ud574\uc57c \ud560 \ud589\ub3d9\uc744 \uc9e7\uac8c \ud655\uc778\ud558\uace0 \ub9d0\ub85c \ud45c\ud604\ud574 \ubcf8\ub2e4.", "targetSkill": "\uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc5d0\uc11c \uc7a5\uc18c \ud45c\ud604\uacfc \ud574\uc57c \ud560 \ud589\ub3d9 \ud45c\ud604\uc744 \uad6c\ubd84\ud574 \uc77d\uace0, \uc54c\ub9de\uc740 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub530\ub77c \ub9d0\ud558\uae30", "contentType": "learning_focus"}, "stagePlans": [{"unitId": "stage_1", "step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uac1c\ub150 \uc5f4\uae30", "purpose": "\ud559\uad50 \ubcf5\ub3c4\uc5d0 \ubd99\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38 \uc7a5\uba74\uc744 \uba3c\uc800 \ubcf4\uc5ec\uc8fc\uace0, \uc548\ub0b4\ubb38\uc5d0\uc11c \u2018\uc5b4\ub514(\uc7a5\uc18c)\u2019\uc640 \u2018\ubb34\uc5c7\uc744 \ud574\uc57c \ud558\ub294\uc9c0(\ud589\ub3d9)\u2019\ub97c \ub098\ub204\uc5b4 \ubcf4\ub294 \ud65c\ub3d9\uc774\ub77c\ub294 \uc810\uc744 \uc9e7\uac8c \uc548\ub0b4\ud55c\ub2e4.", "templateRationale": "\uae34 \uc124\uba85 \uc5c6\uc774 \uc775\uc219\ud55c \ud559\uad50 \ubcf5\ub3c4 \uc7a5\uba74\uacfc \uc9e7\uc740 \uc548\ub0b4\ubb38 \uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec \uc8fc\uc5b4, \uae00\uc744 \uae38\uac8c \uc77d\uc9c0 \uc54a\uace0\ub3c4 \uc774\ubc88 \ud65c\ub3d9\uc758 \ud575\uc2ec\uc778 \u2018\uc7a5\uc18c \ub2e8\uc5b4\u2019\uc640 \u2018\ud574\uc57c \ud560 \ud589\ub3d9\u2019 \uad6c\ubd84\uc5d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4e4\uc5b4\uac00\ub3c4\ub85d \ud55c\ub2e4."}, {"unitId": "stage_2", "step": 2, "stageRole": "basic_problem", "templateType": "scene_question", "studentTitle": "\ubb38\uc81c 1", "purpose": "\ud55c \uac1c\uc758 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \ubcf4\uace0, \uadf8 \uc548\uc5d0\uc11c \uc7a5\uc18c \ub2e8\uc5b4\uc640 \ud574\uc57c \ud560 \ud589\ub3d9\uc744 \ub098\ub204\uc5b4 \ubb3b\ub294 \uc9e7\uc740 \uc9c8\ubb38\uc73c\ub85c \uccab \uc131\uacf5\uc744 \uc81c\uacf5\ud55c\ub2e4.", "templateRationale": "scene_question \ud15c\ud50c\ub9bf\uc744 \uc0ac\uc6a9\ud574 \uadf8\ub9bc \uc18d \uc548\ub0b4\ud310\uc744 \ud568\uaed8 \ubcf4\uba74\uc11c \uc544\uc8fc \uc9e7\uc740 \ubb38\uc7a5 \uc9c8\ubb38\uc73c\ub85c \u2018\uc774 \uc548\ub0b4\ubb38\uc740 \uc5b4\ub514\uc5d0 \ub300\ud55c \uac70\uc57c?\u2019\ucc98\ub7fc \ud55c \ubc88\uc5d0 \ud55c \uac00\uc9c0\ub9cc \ubb3c\uc5b4 \ud559\uc0dd\uc758 \uc77d\uae30 \ubd80\ub2f4\uc744 \uc904\uc774\uace0, \uc2dc\uac01 \ub2e8\uc11c\uc5d0 \uae30\ub300\uc5b4 \uc7a5\uc18c-\ud589\ub3d9\uc744 \uad6c\ubd84\ud558\ub294 \uc5f0\uc2b5\uc744 \ud55c\ub2e4."}, {"unitId": "stage_3", "step": 3, "stageRole": "applied_problem", "templateType": "blank_fill", "studentTitle": "\ubb38\uc81c 2", "purpose": "\ube44\uc2b7\ud55c \ud615\uc2dd\uc758 \ub2e4\ub978 \uc548\ub0b4\ubb38\uc5d0\uc11c, \ube44\uc5b4 \uc788\ub294 \u2018\uc7a5\uc18c\u2019 \ub610\ub294 \u2018\ud574\uc57c \ud560 \ud589\ub3d9\u2019\uc744 \uace8\ub77c \ub123\uc73c\uba74\uc11c \uc7a5\uc18c-\ud589\ub3d9 \uc9dd\uc744 \ub2e4\uc2dc \ud55c \ubc88 \uad6c\ubd84\ud574 \ubcf8\ub2e4.", "templateRationale": "blank_fill \ud15c\ud50c\ub9bf\uc744 \uc0ac\uc6a9\ud574 \uc9e7\uc740 \uc548\ub0b4\ubb38\uc5d0\uc11c \ube60\uc9c4 \ud55c \ubd80\ubd84\ub9cc \uc120\ud0dd\ud558\uac8c \ud568\uc73c\ub85c\uc368, \uae00 \uc804\uccb4\ub97c \uc0c8\ub85c \uc77d\uc9c0 \uc54a\uace0\ub3c4 \uc55e\uc5d0\uc11c \ubcf8 \uc7a5\uc18c-\ud589\ub3d9 \uad6c\uc870\ub97c \uc751\uc6a9\ud574 \ubcf4\ub294 \ud65c\ub3d9\uc744 \uc81c\uacf5\ud55c\ub2e4. \uc120\ud0dd\uc9c0\ub294 2\uac1c\ub85c \uc904\uc5ec \uc548\uc815\uac10\uc744 \uc720\uc9c0\ud55c\ub2e4."}, {"unitId": "stage_4", "step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "purpose": "\uc9c0\uae08\uae4c\uc9c0 \ubcf8 \uc548\ub0b4\ubb38 \uc608\uc2dc\ub97c \ub5a0\uc62c\ub9ac\uba70, \uc2a4\uc2a4\ub85c \u2018\uc7a5\uc18c+\ud574\uc57c \ud560 \ud589\ub3d9\u2019\uc73c\ub85c \uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \ub9d0\ub85c \ub9cc\ub4e4\uc5b4 \ubcf4\uac70\ub098, \uc8fc\uc5b4\uc9c4 \uc548\ub0b4\ubb38\uc744 \uc18c\ub9ac \ub0b4\uc5b4 \uc77d\uc5b4 \ubcf8\ub2e4.", "templateRationale": "realtime_teach_back \ud615\uc2dd\uc73c\ub85c \ud559\uc0dd\uc774 \u2018Library \u2013 Be quiet\u2019\ucc98\ub7fc \uc7a5\uc18c\uc640 \ud589\ub3d9\uc774 \uc9dd\uc9c0\uc5b4\uc9c4 \uc9e7\uc740 \ubb38\uc7a5\uc744 \uc9c1\uc811 \ub9d0\ud574\ubcf4\uac8c \ud558\uc5ec, \uc548\ub0b4\ubb38\uc744 \ubcf4\uace0 \ud575\uc2ec\ub9cc \ubf51\uc544 \ub9d0\ud558\ub294 \uc5f0\uc2b5\uc774 \uc2e4\uc81c \ub9d0\ud558\uae30 \uc0c1\ud669\uc73c\ub85c \uc774\uc5b4\uc9c0\uac8c \ud55c\ub2e4."}], "visualSpecDrafts": [{"unitId": "visual_hero", "assetRole": "hero", "step": 0, "visualPurpose": "\uc804\uccb4 \ud65c\ub3d9\uc758 \ubc30\uacbd\uc774 \ub418\ub294 \ud559\uad50 \ubcf5\ub3c4\uc640 \uc601\uc5b4 \uc548\ub0b4\ud310 \ubd84\uc704\uae30\ub97c \uc804\ub2ec\ud55c\ub2e4.", "sceneSummary": "\ucd08\ub4f1\ud559\uad50 \uc2e4\ub0b4 \ubcf5\ub3c4 \ubcbd\uc5d0 \uc5ec\ub7ec \uac1c\uc758 \uc601\uc5b4 \uc548\ub0b4\ud310\uc774 \ubd99\uc5b4 \uc788\uace0, \uac01 \uc548\ub0b4\ud310\uc5d0\ub294 \uc7a5\uc18c\uc640 \uac04\ub2e8\ud55c \ud589\ub3d9 \ubb38\uad6c\uac00 \ud568\uaed8 \uc801\ud600 \uc788\ub2e4.", "primaryEvidenceObject": "\ubcf5\ub3c4 \ubcbd\uc5d0 \ubd99\uc740 \uc601\uc5b4 \uc548\ub0b4\ud310", "evidenceLocation": "\ubcf5\ub3c4 \ubcbd \uc911\uc559 \ubd80\ubd84", "mustShow": ["\uc2e4\ub0b4 \ud559\uad50 \ubcf5\ub3c4", "\ubcf5\ub3c4 \ubcbd\uc5d0 \uba87 \uac1c\uc758 \uc548\ub0b4\ud310\uc774 \ub098\ub780\ud788 \ubd99\uc5b4 \uc788\uc74c", "\uac01 \uc548\ub0b4\ud310\uc5d0 \uc7a5\uc18c\ub97c \ub098\ud0c0\ub0b4\ub294 \uc601\uc5b4 \ub2e8\uc5b4\uc640 \uc9e7\uc740 \ud589\ub3d9 \ubb38\uc7a5\uc774 \ud568\uaed8 \uc801\ud600 \uc788\uc74c(\uc608: Library, Gym, Office \ub4f1)", "\uac04\ub2e8\ud55c \uc544\uc774\ucf58(\ucc45, \uc6b4\ub3d9\ud654, \uc870\uc6a9\ud788 \ud45c\uc2dc \uc544\uc774\ucf58 \ub4f1)"], "allowedSceneText": ["Library", "Gym", "Office", "Be quiet", "Wear sports shoes", "Ask here"], "doNotRenderText": ["problem", "choices", "answer", "feedback", "\uc815\ub2f5", "\ud78c\ud2b8", "\uc810\uc218", "\uc120\uc0dd\ub2d8 \uc124\uba85 \ubb38\uc7a5"], "composition": "\ubcf5\ub3c4 \uc804\uccb4\uac00 \ubcf4\uc774\ub418, \uce74\uba54\ub77c\uac00 \uc548\ub0b4\ud310\uc774 \ubd99\uc5b4 \uc788\ub294 \ubcbd \ucabd\uc744 \ud5a5\ud574 \uc788\uace0, \uc548\ub0b4\ud310\ub4e4\uc774 \ud559\uc0dd \ub208\ub192\uc774 \uc815\ub3c4\uc5d0 \ubc30\uc5f4\ub418\uc5b4 \uc788\ub294 \uad6c\ub3c4"}, {"unitId": "visual_stage_1", "assetRole": "stage_1", "step": 1, "visualPurpose": "\uccab \uc548\ub0b4\ubb38 \uc608\uc2dc\ub97c \ud06c\uac8c \ubcf4\uc5ec \uc8fc\uc5b4, \uc548\ub0b4\ubb38 \uad6c\uc870(\uc704\uc5d0 \uc7a5\uc18c, \uc544\ub798\uc5d0 \ud589\ub3d9)\ub97c \ud55c\ub208\uc5d0 \ubcf4\uac8c \ud55c\ub2e4.", "sceneSummary": "\ubcf5\ub3c4 \ubcbd \ud55c\uac00\uc6b4\ub370\uc5d0 \u2018Library\u2019 \uad00\ub828 \uc601\uc5b4 \uc548\ub0b4\ud310\uc774 \ud06c\uac8c \ubcf4\uc778\ub2e4. \uc704\ucabd\uc5d0\ub294 \u2018Library\u2019, \uc544\ub798\ucabd\uc5d0\ub294 \uc870\uc6a9\ud788 \ud574\uc57c \ud568\uc744 \ub098\ud0c0\ub0b4\ub294 \uc9e7\uc740 \ubb38\uad6c\uc640 \ucc45 \uc544\uc774\ucf58\uc774 \uc788\ub2e4.", "primaryEvidenceObject": "Library \uc548\ub0b4\ud310", "evidenceLocation": "\ud654\uba74 \uc911\uc559", "mustShow": ["\u2018Library\u2019\ub77c\ub294 \uc601\uc5b4 \ub2e8\uc5b4\uac00 \uc801\ud78c \uc548\ub0b4\ud310", "\u2018Be quiet\u2019\ub77c\ub294 \uc9e7\uc740 \uc601\uc5b4 \ubb38\uc7a5 \ub610\ub294 \ube44\uc2b7\ud55c \uc758\ubbf8 \ubb38\uad6c", "\ucc45 \uc544\uc774\ucf58 \ub610\ub294 \uc870\uc6a9\ud788 \ud558\ub77c\ub294 \uc758\ubbf8\uc758 \uadf8\ub9bc(\uc190\uac00\ub77d\uc744 \uc785\uc5d0 \ub300\ub294 \uadf8\ub9bc \ub4f1)", "\ubcf5\ub3c4 \ubcbd \uc77c\ubd80 \ubc30\uacbd"], "allowedSceneText": ["Library", "Be quiet"], "doNotRenderText": ["problem", "choices", "answer", "feedback", "\uc815\ub2f5", "\ud78c\ud2b8", "\uc810\uc218", "\ud559\uc0dd\uc5d0\uac8c \uc8fc\ub294 \uc9c0\uc2dc \ubb38\uc7a5"], "composition": "\ud654\uba74 \uc911\uc559\uc5d0 Library \uc548\ub0b4\ud310\uc774 \ud06c\uac8c \ubcf4\uc774\ub3c4\ub85d \uadfc\uc811 \uad6c\ub3c4\ub85c \uc7a1\uace0, \uc8fc\ubcc0 \ubcf5\ub3c4\ub294 \ud750\ub9bf\ud558\uac8c \ucc98\ub9ac\ud574 \uc548\ub0b4\ud310\uc774 \uc798 \ubcf4\uc774\ub3c4\ub85d \ud55c\ub2e4."}, {"unitId": "visual_stage_2", "assetRole": "stage_2", "step": 2, "visualPurpose": "\ud559\uc0dd\uc774 \uc9c8\ubb38\uc744 \ub4e3\uace0 \ub2f5\uc744 \ucc3e\uc744 \uc218 \uc788\ub3c4\ub85d, \ud55c \uc548\ub0b4\ubb38 \uc804\uccb4\ub97c \uba85\ud655\ud558\uac8c \ubcf4\uc5ec \uc900\ub2e4.", "sceneSummary": "\ubcf5\ub3c4 \ubcbd\uc5d0 \u2018Gym\u2019 \uc548\ub0b4\ud310\uc774 \ubd99\uc5b4 \uc788\uace0, \uc704\uc5d0\ub294 Gym, \uc544\ub798\uc5d0\ub294 \uc6b4\ub3d9\ud654\ub97c \uc2e0\uc73c\ub77c\ub294 \uc9e7\uc740 \ud589\ub3d9 \ubb38\uad6c\uc640 \uc6b4\ub3d9\ud654 \uc544\uc774\ucf58\uc774 \uc788\ub2e4.", "primaryEvidenceObject": "Gym \uc548\ub0b4\ud310", "evidenceLocation": "\ud654\uba74 \uc911\uc559 \uc624\ub978\ucabd", "mustShow": ["\u2018Gym\u2019\uc774\ub77c\ub294 \uc601\uc5b4 \ub2e8\uc5b4\uac00 \uc801\ud78c \uc548\ub0b4\ud310", "\u2018Wear sports shoes\u2019\uc640 \uac19\uc774 \uc6b4\ub3d9\ud654\ub97c \uc2e0\uc73c\ub77c\ub294 \uc9e7\uc740 \ud589\ub3d9 \ubb38\uad6c", "\uc6b4\ub3d9\ud654 \uadf8\ub9bc \uc544\uc774\ucf58", "\ubcf5\ub3c4 \ubcbd\uc758 \uc77c\ubd80"], "allowedSceneText": ["Gym", "Wear sports shoes"], "doNotRenderText": ["problem", "choices", "answer", "feedback", "\uc815\ub2f5", "\ud78c\ud2b8", "\uc810\uc218", "\ud559\uc0dd \uc9c0\uc2dc \ubb38\uc7a5"], "composition": "\ud654\uba74 \uc911\uc559\uc5d0 Gym \uc548\ub0b4\ud310\uc774 \ubcf4\uc774\uace0, \uc548\ub0b4\ud310\uc758 \uae00\uc790\uac00 \ub610\ub837\ud558\uac8c \ubcf4\uc774\ub3c4\ub85d \uac00\uae5d\uac8c \uc7a1\ub294\ub2e4. \uc67c\ucabd\uc5d0\ub294 \ubcf5\ub3c4 \uc77c\ubd80\uac00 \uc0b4\uc9dd \ubcf4\uc774\ub3c4\ub85d \ud55c\ub2e4."}, {"unitId": "visual_stage_3", "assetRole": "stage_3", "step": 3, "visualPurpose": "\uc0c8\ub85c\uc6b4 \uc548\ub0b4\ubb38 \uc608\uc2dc\ub97c \ubcf4\uc5ec \uc8fc\uc5b4, \ube44\uc5b4 \uc788\ub294 \ubd80\ubd84(\uc7a5\uc18c \ub610\ub294 \ud589\ub3d9)\uc744 \ub5a0\uc62c\ub9ac\uba70 \ucc44\uc6b0\ub294 \uc0c1\ud669\uc744 \ub9cc\ub4e0\ub2e4.", "sceneSummary": "\ubcf5\ub3c4 \ub2e4\ub978 \ucabd \ubcbd\uc5d0 \u2018Office\u2019 \uc548\ub0b4\ud310\uc774 \ubd99\uc5b4 \uc788\uace0, \uc704\uc5d0\ub294 Office, \uc544\ub798\uc5d0\ub294 \uc9c8\ubb38\uc774\ub098 \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub77c\ub294 \uc9e7\uc740 \ud589\ub3d9 \ubb38\uad6c\uc640 \ub9d0\ud48d\uc120 \uc544\uc774\ucf58\uc774 \uc788\ub2e4.", "primaryEvidenceObject": "Office \uc548\ub0b4\ud310", "evidenceLocation": "\ud654\uba74 \uc911\uc559", "mustShow": ["\u2018Office\u2019\ub77c\ub294 \uc601\uc5b4 \ub2e8\uc5b4\uac00 \uc801\ud78c \uc548\ub0b4\ud310", "\u2018Ask here\u2019 \ub610\ub294 \ube44\uc2b7\ud55c \uc758\ubbf8\uc758 \uc9e7\uc740 \ud589\ub3d9 \ubb38\uad6c", "\ub9d0\ud48d\uc120 \ubaa8\uc591 \uc544\uc774\ucf58\uc774\ub098 \ubb3c\uc74c\ud45c \uc544\uc774\ucf58", "\ubcf5\ub3c4 \ubcbd \ubc30\uacbd"], "allowedSceneText": ["Office", "Ask here"], "doNotRenderText": ["problem", "choices", "answer", "feedback", "\uc815\ub2f5", "\ud78c\ud2b8", "\uc810\uc218", "\ud559\uc0dd\uc6a9 \ubcf4\uae30 \ubb38\uc7a5"], "composition": "Office \uc548\ub0b4\ud310\uc774 \ud654\uba74 \uc815\uc911\uc559\uc5d0 \uc624\ub3c4\ub85d \uadfc\uc811 \uad6c\ub3c4\ub85c \ubcf4\uc5ec \uc8fc\uace0, \uc548\ub0b4\ubb38 \uae00\uc528\uc640 \uc544\uc774\ucf58\uc774 \ubd84\uba85\ud558\uac8c \ubcf4\uc774\ub3c4\ub85d \ud55c\ub2e4."}, {"unitId": "visual_stage_4_realtime", "assetRole": "stage_4_realtime", "step": 4, "visualPurpose": "\uc5ec\ub7ec \uc548\ub0b4\ubb38\uc774 \ud568\uaed8 \ubcf4\uc774\ub294 \ubcf5\ub3c4 \uc7a5\uba74\uc744 \ubcf4\uc5ec \uc8fc\uc5b4, \ud559\uc0dd\uc774 \uc2e4\uc81c \uc0c1\ud669\ucc98\ub7fc \uc790\uc2e0\uc758 \uc548\ub0b4\ubb38 \ubb38\uc7a5\uc744 \ub9d0\ub85c \ub9cc\ub4e4\uc5b4 \ubcfc \uc218 \uc788\ub3c4\ub85d \ud55c\ub2e4.", "sceneSummary": "\ubcf5\ub3c4 \ubcbd\uc744 \ub530\ub77c Library, Gym, Office \uc548\ub0b4\ud310\uc774 \uc77c\uc815 \uac04\uaca9\uc73c\ub85c \ub098\ub780\ud788 \ubd99\uc5b4 \uc788\uace0, \ubcf5\ub3c4\ub97c \uac77\ub294 \ud559\uc0dd \uc2e4\ub8e8\uc5e3\uc774 \uc791\uac8c \ubcf4\uc778\ub2e4.", "primaryEvidenceObject": "\uc5ec\ub7ec \uac1c\uc758 \uc601\uc5b4 \uc548\ub0b4\ud310", "evidenceLocation": "\ubcf5\ub3c4 \ubcbd\uc744 \ub530\ub77c \ubc18\ubcf5\uc801\uc73c\ub85c \ubc30\uce58", "mustShow": ["Library, Gym, Office \uc548\ub0b4\ud310\uc774 \ud55c \ud654\uba74 \uc548\uc5d0 \ubaa8\ub450 \ubcf4\uc784", "\uac01 \uc548\ub0b4\ud310\uc5d0 \uac04\ub2e8\ud55c \ud589\ub3d9 \ubb38\uad6c\uc640 \uc544\uc774\ucf58\uc774 \ud568\uaed8 \uc788\uc74c", "\ubcf5\ub3c4\ub97c \uac77\ub294 \ud559\uc0dd \ud55c \uba85\uc758 \ub4b7\ubaa8\uc2b5 \ub610\ub294 \uc606\ubaa8\uc2b5"], "allowedSceneText": ["Library", "Be quiet", "Gym", "Wear sports shoes", "Office", "Ask here"], "doNotRenderText": ["problem", "choices", "answer", "feedback", "\uc815\ub2f5", "\ud78c\ud2b8", "\uc810\uc218", "\ub300\ud654 \ub9d0\ud48d\uc120 \ud14d\uc2a4\ud2b8"], "composition": "\ubcf5\ub3c4 \uae38\uac8c \ubed7\uc740 \uc6d0\uadfc\uac10\uc774 \ub290\uaef4\uc9c0\ub3c4\ub85d \uc0ac\uc120 \uad6c\ub3c4\ub85c \uc7a1\uace0, \ubcbd\uc5d0 \ubd99\uc740 \uc5ec\ub7ec \uc548\ub0b4\ud310\uc774 \uc624\ub978\ucabd\uc73c\ub85c \uc774\uc5b4\uc838 \ubcf4\uc774\uac8c \ud55c\ub2e4. \ud559\uc0dd\uc740 \uc67c\ucabd \uc544\ub798 \ucabd\uc5d0 \uc791\uac8c \ubc30\uce58\ud55c\ub2e4."}], "assetIntent": {"imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\uc804\uccb4 \ud65c\ub3d9 \ub9e5\ub77d\uc744 \ud55c\ub208\uc5d0 \ubcf4\uc5