sset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_3", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_3_audio", "visualSpec": {"unitId": "visual_stage_3", "assetRole": "stage_3", "step": 3, "visualPurpose": "\uc0c8\ub85c\uc6b4 \uc548\ub0b4\ubb38 \uc608\uc2dc\ub97c \ubcf4\uc5ec \uc8fc\uc5b4, \ube44\uc5b4 \uc788\ub294 \ubd80\ubd84(\uc7a5\uc18c \ub610\ub294 \ud589\ub3d9)\uc744 \ub5a0\uc62c\ub9ac\uba70 \ucc44\uc6b0\ub294 \uc0c1\ud669\uc744 \ub9cc\ub4e0\ub2e4.", "sceneSummary": "\ubcf5\ub3c4 \ub2e4\ub978 \ucabd \ubcbd\uc5d0 \u2018Office\u2019 \uc548\ub0b4\ud310\uc774 \ubd99\uc5b4 \uc788\uace0, \uc704\uc5d0\ub294 Office, \uc544\ub798\uc5d0\ub294 \uc9c8\ubb38\uc774\ub098 \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub77c\ub294 \uc9e7\uc740 \ud589\ub3d9 \ubb38\uad6c\uc640 \ub9d0\ud48d\uc120 \uc544\uc774\ucf58\uc774 \uc788\ub2e4.", "primaryEvidenceObject": "Office \uc548\ub0b4\ud310", "evidenceLocation": "\ud654\uba74 \uc911\uc559", "mustShow": ["\u2018Office\u2019\ub77c\ub294 \uc601\uc5b4 \ub2e8\uc5b4\uac00 \uc801\ud78c \uc548\ub0b4\ud310", "\u2018Ask here\u2019 \ub610\ub294 \ube44\uc2b7\ud55c \uc758\ubbf8\uc758 \uc9e7\uc740 \ud589\ub3d9 \ubb38\uad6c", "\ub9d0\ud48d\uc120 \ubaa8\uc591 \uc544\uc774\ucf58\uc774\ub098 \ubb3c\uc74c\ud45c \uc544\uc774\ucf58", "\ubcf5\ub3c4 \ubcbd \ubc30\uacbd"], "allowedSceneText": ["Office", "Ask here"], "doNotRenderText": ["problem", "choices", "answer", "feedback", "\uc815\ub2f5", "\ud78c\ud2b8", "\uc810\uc218", "\ud559\uc0dd\uc6a9 \ubcf4\uae30 \ubb38\uc7a5"], "composition": "Office \uc548\ub0b4\ud310\uc774 \ud654\uba74 \uc815\uc911\uc559\uc5d0 \uc624\ub3c4\ub85d \uadfc\uc811 \uad6c\ub3c4\ub85c \ubcf4\uc5ec \uc8fc\uace0, \uc548\ub0b4\ubb38 \uae00\uc528\uc640 \uc544\uc774\ucf58\uc774 \ubd84\uba85\ud558\uac8c \ubcf4\uc774\ub3c4\ub85d \ud55c\ub2e4."}}, {"unitId": "stage_4", "step": 4, "stageId": "stage_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_4", "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "studentInstruction": "\uc9c0\uae08\uae4c\uc9c0 \ubcf8 \uc548\ub0b4\ud310\uc744 \ub5a0\uc62c\ub9ac\uba70, \u2018\uc7a5\uc18c + \ud574\uc57c \ud560 \ud589\ub3d9\u2019\uc774 \ub4e4\uc5b4\uac04 \uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \ud55c\ub450 \uac1c \ub9cc\ub4e4\uc5b4\uc11c \uc18c\ub9ac \ub0b4\uc5b4 \ub9d0\ud574 \ubcf4\uc138\uc694.", "templateJson": {"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime_audio"}, "situationText": "\ubcf5\ub3c4\uc5d0 \ubcf4\uc774\ub294 Library, Gym, Office \uc548\ub0b4\ud310\uc744 \ub5a0\uc62c\ub9ac\uba70, \u2018\uc7a5\uc18c + \ud574\uc57c \ud560 \ud589\ub3d9\u2019 \ubb38\uc7a5\uc744 \uc2a4\uc2a4\ub85c \ub9d0\ud574 \ubd05\uc2dc\ub2e4.", "practicePrompt": "\uc608\ub97c \ub4e4\uc5b4 \u2018Library \u2013 Be quiet\u2019\ucc98\ub7fc, \uc7a5\uc18c\uc640 \ud574\uc57c \ud560 \ud589\ub3d9\uc774 \ud568\uaed8 \ub4e4\uc5b4\uac04 \uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \ud55c \ubb38\uc7a5\uc529 \ub9d0\ud574 \ubcf4\uc138\uc694.", "sourceTextLines": ["Library \u2013 Be quiet", "Gym \u2013 Wear sports shoes", "Office \u2013 Ask here"], "sceneTextLines": ["Library", "Be quiet", "Gym", "Wear sports shoes", "Office", "Ask here"]}, "realtimeSpec": {"id": "rt_spec_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a", "stageId": "stage_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\uc124\uba85\ud574\ubcf4\uae30", "situationText": "\ud559\uad50 \ubcf5\ub3c4\ub97c \uac78\uc73c\uba74\uc11c Library, Gym, Office \uc548\ub0b4\ud310\uc744 \ubcf8\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc138\uc694. \uac01 \uc7a5\uc18c\uc5d0\uc11c \ud574\uc57c \ud560 \uc77c\uc744 \uc9e7\uc740 \uc601\uc5b4 \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud574 \ubd05\ub2c8\ub2e4.", "aiRole": "\uce5c\uc808\ud558\uac8c \ud568\uaed8 \uc5f0\uc2b5\ud574 \uc8fc\ub294 \uc601\uc5b4 \uc120\uc0dd\ub2d8", "openingLine": "\ubcf5\ub3c4\uc5d0 \uc601\uc5b4 \uc548\ub0b4\ud310\uc774 \ubcf4\uc774\ub124\uc694. \uc6b0\ub9ac\uac00 \ubcf8 \uac83\ucc98\ub7fc, \ud55c \uc548\ub0b4\ubb38\uc5d0 \u2018\uc7a5\uc18c\u2019\uc640 \u2018\ud574\uc57c \ud560 \ud589\ub3d9\u2019\uc744 \ub123\uc5b4\uc11c \ud55c\ub450 \ubb38\uc7a5\uc744 \ub9d0\ud574 \ubcfc\uae4c\uc694?", "studentGoal": "Library, Gym, Office \uac19\uc740 \uc7a5\uc18c \ub2e8\uc5b4\uc640 Be quiet, Wear sports shoes, Ask here \uac19\uc740 \ud589\ub3d9 \ubb38\uc7a5\uc744 \uc9dd\uc9c0\uc5b4, \uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \uc2a4\uc2a4\ub85c \ud55c\ub450 \uac1c \ub9d0\ud574 \ubcf8\ub2e4.", "rubric": [{"id": "r1", "label": "\uc7a5\uc18c \ub2e8\uc5b4(Library, Gym, Office \ub4f1)\ub97c \ub610\ub837\ud558\uac8c \ub9d0\ud55c\ub2e4.", "required": true}, {"id": "r2", "label": "\ud574\uc57c \ud560 \ud589\ub3d9 \ubb38\uc7a5(Be quiet, Wear sports shoes, Ask here \ub4f1)\uc744 \ud568\uaed8 \ubd99\uc5ec \ub9d0\ud55c\ub2e4.", "required": true}, {"id": "r3", "label": "\ud55c \ubc88\uc5d0 \ud55c \uc548\ub0b4\ubb38\uc529 \uc9e7\uac8c \ub9d0\ud55c\ub2e4.", "required": false}, {"id": "r4", "label": "\ub73b\uc774 \uc870\uae08 \ub2ec\ub77c\ub3c4 \uc7a5\uc18c+\ud589\ub3d9 \uad6c\uc870\ub97c \uc720\uc9c0\ud55c\ub2e4.", "required": false}, {"id": "r5", "label": "\ub9c9\ud788\uba74 \uc7a0\uae50 \u