);
INSERT INTO memory_cards VALUES('memory_student_테스트가람_ebd58e17','student_테스트가람_ebd58e17','case_student_테스트가람_ebd58e17',1,'["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791, \uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac\uc5d0\uc11c \ud575\uc2ec \ub2e8\uc11c\ub97c \uba3c\uc800 \ud655\uc778\ud558\uace0 \uc9e7\uc740 \ub2e8\uacc4\ub85c \uac1c\ub150\uc744 \uc124\uba85\ud558\uae30"]','{"registrationObservation": "\uc9e7\uc740 \uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \ubcf4\uba74 \ub530\ub77c \uc77d\uace0, \uae34 \uc124\uba85\ubcf4\ub2e4 \ubcf4\uae30 \ub2e8\uc11c\ub97c \uba3c\uc800 \ud655\uc778\ud560 \ub54c \uc548\uc815\uc801\uc785\ub2c8\ub2e4.", "strengths": ["\uc9e7\uc740 \uc9c0\uc2dc\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.", "\uc608\uc2dc \ubb38\uc7a5\uc744 \ubcf4\uace0 \ub530\ub77c \ub9d0\ud569\ub2c8\ub2e4."], "weaknesses": ["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694.", "\uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."], "preferredSupports": ["\uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\uc9c0\uc2dc\ub97c \uc9e7\uac8c \ub098\ub214", "\uc120\ud0dd\uc9c0\ub97c \uc904\uc784"], "supportIntake": {"sourceBasis": ["\uc13c\ud130 \uad00\ucc30 \uc790\ub8cc\uc758 \uae30\ub2a5\ud3c9\uac00 \uad00\uc810", "QABF\uc758 \ud589\ub3d9 \uae30\ub2a5 \uac00\uc124 \uad00\uc810", "\ub3c4\uc804\uc801 \ud589\ub3d9 \uc6b0\uc120\uc21c\uc704 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\uc758 \uc9c0\uc6d0 \uc6b0\uc120\uc21c\uc704 \uad00\uc810"], "learningResponse": {"observedStrengths": ["\uc9e7\uc740 \uc9c0\uc2dc\ub97c \uc774\ud574\ud568", "\uc608\uc2dc \ubb38\uc7a5\uc744 \ubcf4\uace0 \ub530\ub77c \ub9d0\ud568"], "effectiveSupports": ["\uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\uc9c0\uc2dc\ub97c \uc9e7\uac8c \ub098\ub214", "\uc120\ud0dd\uc9c0\ub97c \uc904\uc784"], "readingLoad": "low", "instructionBurdens": ["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791", "\uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac"], "communicationNeeds": ["\ub2e4\uc2dc \ub9d0\ud574\ub2ec\ub77c\uace0 \uc694\uccad", "\uc21c\uc11c \ud655\uc778 \uc9c8\ubb38"], "choiceCountLimit": 2}, "checklistSummary": {"observedStrengths": ["\uc9e7\uc740 \uc9c0\uc2dc\ub97c \uc774\ud574\ud568", "\uc608\uc2dc \ubb38\uc7a5\uc744 \ubcf4\uace0 \ub530\ub77c \ub9d0\ud568"], "hardSituations": ["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791", "\uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac"], "effectiveSupports": ["\uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\uc9c0\uc2dc\ub97c \uc9e7\uac8c \ub098\ub214", "\uc120\ud0dd\uc9c0\ub97c \uc904\uc784"], "instructionBurdens": ["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791", "\uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac"], "communicationNeeds": ["\ub2e4\uc2dc \ub9d0\ud574\ub2ec\ub77c\uace0 \uc694\uccad", "\uc21c\uc11c \ud655\uc778 \uc9c8\ubb38"], "calmingSupports": ["\uae30\ub2e4\ub9b4 \uc2dc\uac04\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428"], "avoidGuidance": ["\uc624\ub958 \uc9c1\ud6c4 \uc7ac\ucd09", "\uae34 \uc124\uba85\ubd80\ud130 \uc2dc\uc791"]}, "replacementSkills": ["\ub2e4\uc2dc \ub9d0\ud574\ub2ec\ub77c\uace0 \uc694\uccad", "\uc21c\uc11c \ud655\uc778 \uc9c8\ubb38"], "recommendedScaffolds": ["\uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\uc9c0\uc2dc\ub97c \uc9e7\uac8c \ub098\ub214", "\uc120\ud0dd\uc9c0\ub97c \uc904\uc784", "\uae30\ub2e4\ub9b4 \uc2dc\uac04\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428"], "avoidGuidance": ["\uc624\ub958 \uc9c1\ud6c4 \uc7ac\ucd09", "\uae34 \uc124\uba85\ubd80\ud130 \uc2dc\uc791"], "teacherObservation": "\uc9e7\uc740 \uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \ubcf4\uba74 \ub530\ub77c \uc77d\uace0, \uae34 \uc124\uba85\ubcf4\ub2e4 \ubcf4\uae30 \ub2e8\uc11c\ub97c \uba3c\uc800 \ud655\uc778\ud560 \ub54c \uc548\uc815\uc801\uc785\ub2c8\ub2e4."}, "supportProfile": {"profileVersion": "support_profile_v1", "draftLabel": "\uc218\uc5c5 \uc124\uacc4 \ucd08\uc548", "lessonDesignHints": ["\uad00\ucc30\ub41c \uac15\uc810\uc740 \uc9e7\uc740 \uc9c0\uc2dc\ub97c \uc774\ud574\ud568, \uc608\uc2dc \ubb38\uc7a5\uc744 \ubcf4\uace0 \ub530\ub77c \ub9d0\ud568\uc785\ub2c8\ub2e4. \uc218\uc5c5\uc5d0\uc11c\ub294 \uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c, \uc9c0\uc2dc\ub97c \uc9e7\uac8c \ub098\ub214\uc744 \uba3c\uc800 \uc801\uc6a9\ud574 \uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791, \uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac \ubd80\ub2f4\uc744 \uc904\uc785\ub2c8\ub2e4.", "\ud604\uc7ac \uc9c0\uc6d0 \ucd08\uc810\uc740 \uc218\uc5c5 \ubc29\uc2dd \uc870\uc815\uc5d0\ub9cc \ud65c\uc6a9\ud558\uace0, \ucf58\ud150\uce20 \uc8fc\uc81c\ub294 \uc0dd\uc131 \uc694\uccad\uc744 \uc6b0\uc120\ud569\ub2c8\ub2e4."], "learningResponsePattern": {"worksWell": ["\uc9e7\uc740 \uc9c0\uc2dc\ub97c \uc774\ud574\ud568", "\uc608\uc2dc \ubb38\uc7a5\uc744 \ubcf4\uace0 \ub530\ub77c \ub9d0\ud568"], "canBeHard": ["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791", "\uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac"], "choiceCountLimit": 2, "readingLoad": "low", "explanationStyle": "\uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ud55c \ub2e8\uacc4\uc529 \ud655\uc778"}, "behaviorSupportProfile": {"priorityBehaviors": [], "functionHypotheses": [], "replacementSkills": ["\ub2e4\uc2dc \ub9d0\ud574\ub2ec\ub77c\uace0 \uc694\uccad", "\uc21c\uc11c \ud655\uc778 \uc9c8\ubb38"], "recommendedScaffolds": ["\uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\uc9c0\uc2dc\ub97c \uc9e7\uac8c \ub098\ub214", "\uc120\ud0dd\uc9c0\ub97c \uc904\uc784", "\uae30\ub2e4\ub9b4 \uc2dc\uac04\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428"]}, "strengths": ["\uc9e7\uc740 \uc9c0\uc2dc\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.", "\uc608\uc2dc \ubb38\uc7a5\uc744 \ubcf4\uace0 \ub530\ub77c \ub9d0\ud569\ub2c8\ub2e4."], "supportCautions": ["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694.", "\uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."], "source": {"intakeSourceId": "support_intake_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_7e1e4709", "generatedBy": "local_demo_ai", "rawRecordPreserved": true}, "teacherNote": "\uccab \uc790\ub8cc\ub294 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \uc9e7\uac8c \ubcf4\uace0 \uc7a5\uc18c\uc640 \ud589\ub3d9\uc744 \uad6c\ubd84\ud558\ub294 \ud750\ub984\uc73c\ub85c \ud655\uc778\ud569\ub2c8\ub2e4.", "confirmedAt": "2026-05-08T11:49:51.601394+00:00"}, "supportProfileConfirmedAt": "2026-05-08T11:49:51.601394+00:00"}','짧은 예시 문장을 먼저 보면 따라 읽고, 긴 설명보다 보기 단서를 먼저 확인할 때 안정적입니다.','["\uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\uc9c0\uc2dc\ub97c \uc9e7\uac8c \ub098\ub214", "\uc120\ud0dd\uc9c0\ub97c \uc904\uc784", "\uc9e7\uc740 \uc9c0\uc2dc\ub97c \uc774\ud574\ud568", "\uc608\uc2dc \ubb38\uc7a5\uc744 \ubcf4\uace0 \ub530\ub77c \ub9d0\ud568", "\uae30\ub2e4\ub9b4 \uc2dc\uac04\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428"]','["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694.", "\uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."]',NULL,'["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694.", "\uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."]','2026-05-08T11:49:51.601629+00:00','active');
CREATE TABLE planner_items (
	id VARCHAR NOT NULL, 
