 "realtime_teach_back", "imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\uc124\uba85\ud574\ubcf4\uae30", "situationText": "\ud559\uad50 \ubcf5\ub3c4\ub97c \uac78\uc73c\uba74\uc11c Library, Gym, Office \uc548\ub0b4\ud310\uc744 \ubcf8\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc138\uc694. \uac01 \uc7a5\uc18c\uc5d0\uc11c \ud574\uc57c \ud560 \uc77c\uc744 \uc9e7\uc740 \uc601\uc5b4 \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud574 \ubd05\ub2c8\ub2e4.", "aiRole": "\uce5c\uc808\ud558\uac8c \ud568\uaed8 \uc5f0\uc2b5\ud574 \uc8fc\ub294 \uc601\uc5b4 \uc120\uc0dd\ub2d8", "openingLine": "\ubcf5\ub3c4\uc5d0 \uc601\uc5b4 \uc548\ub0b4\ud310\uc774 \ubcf4\uc774\ub124\uc694. \uc6b0\ub9ac\uac00 \ubcf8 \uac83\ucc98\ub7fc, \ud55c \uc548\ub0b4\ubb38\uc5d0 \u2018\uc7a5\uc18c\u2019\uc640 \u2018\ud574\uc57c \ud560 \ud589\ub3d9\u2019\uc744 \ub123\uc5b4\uc11c \ud55c\ub450 \ubb38\uc7a5\uc744 \ub9d0\ud574 \ubcfc\uae4c\uc694?", "studentGoal": "Library, Gym, Office \uac19\uc740 \uc7a5\uc18c \ub2e8\uc5b4\uc640 Be quiet, Wear sports shoes, Ask here \uac19\uc740 \ud589\ub3d9 \ubb38\uc7a5\uc744 \uc9dd\uc9c0\uc5b4, \uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \uc2a4\uc2a4\ub85c \ud55c\ub450 \uac1c \ub9d0\ud574 \ubcf8\ub2e4.", "rubric": [{"id": "r1", "label": "\uc7a5\uc18c \ub2e8\uc5b4(Library, Gym, Office \ub4f1)\ub97c \ub610\ub837\ud558\uac8c \ub9d0\ud55c\ub2e4.", "required": true}, {"id": "r2", "label": "\ud574\uc57c \ud560 \ud589\ub3d9 \ubb38\uc7a5(Be quiet, Wear sports shoes, Ask here \ub4f1)\uc744 \ud568\uaed8 \ubd99\uc5ec \ub9d0\ud55c\ub2e4.", "required": true}, {"id": "r3", "label": "\ud55c \ubc88\uc5d0 \ud55c \uc548\ub0b4\ubb38\uc529 \uc9e7\uac8c \ub9d0\ud55c\ub2e4.", "required": false}, {"id": "r4", "label": "\ub73b\uc774 \uc870\uae08 \ub2ec\ub77c\ub3c4 \uc7a5\uc18c+\ud589\ub3d9 \uad6c\uc870\ub97c \uc720\uc9c0\ud55c\ub2e4.", "required": false}, {"id": "r5", "label": "\ub9c9\ud788\uba74 \uc7a0\uae50 \uc26c\uace0 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uac70\ub098, \ub2e4\uc2dc \ub9d0\ud574 \ub2ec\ub77c\uace0 \uc694\uccad\ud55c\ub2e4.", "required": false}], "allowedFeedback": ["\ud559\uc0dd\uc774 \ub9d0\ud55c \ubb38\uc7a5\uc5d0\uc11c \uc798 \ub098\uc628 \ubd80\ubd84\uc744 \uba3c\uc800 \ub9d0\ud574 \uc8fc\uace0, \ube60\uc9c4 \uc7a5\uc18c\ub098 \ud589\ub3d9 \ud45c\ud604\uc744 \ud55c \uac00\uc9c0\ub9cc \uc9da\uc5b4 \uc8fc\uba70 \ub2e4\uc2dc \ub9d0\ud574 \ubcf4\ub3c4\ub85d gently \uc81c\uc548\ud569\ub2c8\ub2e4.", "\ud559\uc0dd\uc774 \ub9c9\ud790 \ub54c\ub294 \uc608\uc2dc \ud55c \ubb38\uc7a5(Library \u2013 Be quiet \ub4f1)\uc744 \ucc9c\ucc9c\ud788 \ub2e4\uc2dc \ub4e4\ub824 \uc8fc\uace0, \ube44\uc2b7\ud55c \uad6c\uc870\ub85c \ub530\ub77c \ub9d0\ud574 \ubcf4\ub3c4\ub85d \uc720\ub3c4\ud569\ub2c8\ub2e4.", "\ubc1c\uc74c\uc774 \uc644\ubcbd\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc758\ubbf8\uac00 \uc804\ub2ec\ub418\uba74 \ucda9\ubd84\ud558\ub2e4\uace0 \uc54c\ub824 \uc8fc\uba70, \ud55c \ub2e8\uc5b4\uc529 \ub04a\uc5b4 \uc5f0\uc2b5\ud558\ub3c4\ub85d \ub3d5\uc2b5\ub2c8\ub2e4."], "forbidden": ["\uc815\ub2f5 \ubb38\uc7a5\uc744 \uadf8\ub300\ub85c \uba3c\uc800 \ub9d0\ud574 \uc8fc\uace0 \ud559\uc0dd\uc5d0\uac8c \uadf8\ub300\ub85c \ub530\ub77c \ud558\ub77c\uace0\ub9cc \uc2dc\ud0a4\uc9c0 \uc54a\uae30", "\uc5ec\ub7ec \ubb38\uc7a5\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc694\uad6c\ud558\uac70\ub098 \uc7ac\ucd09\ud574\uc11c \ube60\ub974\uac8c \ub9d0\ud558\uac8c \ud558\uc9c0 \uc54a\uae30", "\ubc1c\uc74c \uc2e4\uc218\ub098 \ub9c9\ud798\uc744 \uc9c0\uc801\ub9cc \ud558\uace0 \uad6c\uccb4\uc801\uc778 \ub2e4\uc74c \uc2dc\ub3c4\ub97c \uc548\ub0b4\ud558\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 180, "postPracticeReflection": ["\uc624\ub298 \ub0b4\uac00 \uc81c\uc77c \ub9d0\ud558\uae30 \ud3b8\ud588\ub358 \uc548\ub0b4\ubb38 \ud55c \ubb38\uc7a5\uc744 \ub5a0\uc62c\ub824 \ubcfc\uae4c\uc694?", "\uc7a5\uc18c\uc640 \ud574\uc57c \ud560 \ud589\ub3d9 \uc911\uc5d0\uc11c, \ub2e4\uc74c\uc5d0 \ub610 \uc5f0\uc2b5\