 "updatedAt": "2026-05-08T12:04:54.391917+00:00", "storageUrl": "/generated/assets/students/student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17/content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a/asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_2.png", "previewUrl": "/generated/assets/students/student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17/content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a/asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_2.png", "qaStatus": "passed", "approvalStatus": "pending"}, {"assetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_3", "assetRole": "stage_3", "assetType": "image", "stageId": "stage_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_3", "status": "succeeded", "errorCode": null, "errorMessage": null, "updatedAt": "2026-05-08T12:05:54.866626+00:00", "storageUrl": "/generated/assets/students/student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17/content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a/asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_3.png", "previewUrl": "/generated/assets/students/student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17/content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a/asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_3.png", "qaStatus": "passed", "approvalStatus": "pending"}, {"assetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime", "assetRole": "stage_4_realtime", "assetType": "image", "stageId": "stage_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_4", "status": "succeeded", "errorCode": null, "errorMessage": null, "updatedAt": "2026-05-08T12:06:11.914892+00:00", "storageUrl": "/generated/assets/students/student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17/content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a/asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime.png", "previewUrl": "/generated/assets/students/student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17/content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a/asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime.png", "qaStatus": "passed", "approvalStatus": "pending"}], "errorCode": null, "errorMessage": null}]}','신규 학생 기준 콘텐츠 생성, 이미지·음성 연결 확인 후 승인합니다.','user_teacher_demo','2026-05-08T12:06:31.908097+00:00','2026-05-08T12:06:31.930224+00:00');
CREATE TABLE content_stages (
	id VARCHAR NOT NULL, 
	mission_content_id VARCHAR NOT NULL, 
	step INTEGER NOT NULL, 
	stage_role VARCHAR NOT NULL, 
	template_type VARCHAR NOT NULL, 
	student_title VARCHAR NOT NULL, 
	student_instruction TEXT NOT NULL, 
	template_json JSON NOT NULL, 
	realtime_spec_json JSON, 
	sort_order INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(mission_content_id) REFERENCES mission_contents (id)
);
INSERT INTO content_stages VALUES('stage_content_student_테스트가람_ebd58e17_1778241784_3199ba2a_1','content_student_테스트가람_ebd58e17_1778241784_3199ba2a',1,'concept_intro','concept_intro','개념 열기','복도 그림에서 영어 안내판 하나를 먼저 보고, 위에 있는 장소와 아래에 있는 행동을 소리 내어 따라 읽어 봅시다.','{"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_1", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_1_audio", "assetBundle": {"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_1", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_1_audio"}, "storyText": "\ud559\uad50 \ubcf5\ub3c4 \ubcbd\uc5d0 \uc601\uc5b4 \uc548\ub0b4\ud310\uc774 \ubd99\uc5b4 \uc788\uc5b4\uc694. \uc704\uc5d0\ub294 \uc7a5\uc18c \uc774\ub984, \uc544\ub798\uc5d0\ub294 \uadf8\uacf3\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub294\uc9c0\uac00 \uc9e7\uac8c \uc4f0\uc5ec \uc788\uc5b4\uc694.", "missionText": "\uc9c0\uae08 \ubcf4\uc774\ub294 Library \uc548\ub0b4\ud310\uc5d0\uc11c, \uc704\uc758 \uc7a5\uc18c \ub2e8\uc5b4\uc640 \uc544\ub798\uc758 \ud574\uc57c \ud560 \ud589\ub3d9 \ubb38\uc7a5\uc744 \ucc28\ub840\ub300\ub85c \ub208\uc73c\ub85c \ubcf4\uace0, \uc120\uc0dd\ub2d8 \ubaa9\uc18c\ub9ac\ub97c \ub4e4\uc73c\uba70 \uc870\uc6a9\ud788 \ud55c \ubc88 \ub530\ub77c \ub9d0\ud574 \ubcf4\uc138\uc694.", "sourceTextLines": ["Library", "Be quiet"], "sceneTextLines": ["Library", "Be quiet"]}','null',1);
INSERT INTO content_stages VALUES('stage_content_student_테스트가람_ebd58e17_1778241784_3199ba2a_2','content_student_테스트가람_ebd58e17_1778241784_3199ba2a',2,'basic_problem','scene_question','문제 1','Gym 안내판을 보고, 이번에는 장소만 먼저 골라 봅시다. 보기 두 개 중에서 안내판 위에 쓰인 장소를 고르세요.','{"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_2", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_2_audio", "assetBundle": {"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_2", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_2_audio"}, "question": "Gym \uc548\ub0b4\ud310\uc5d0\uc11c \u2018\uc5b4\ub514(\uc7a5\uc18c)\u2019\ub97c \ub098\ud0c0\ub0b4\ub294 \uc601\uc5b4 \ub2e8\uc5b4\ub294 \ubb34\uc5c7\uc778\uac00\uc694?", "choices": [{"id": "a", "text": "Gym"}, {"id": "b", "text": "Wear sports shoes"}], "answer": "a", "correctFeedback": "\uc798 \ucc3e\uc558\uc5b4\uc694. Gym\uc774 \u2018\uccb4\uc721\uad00\u2019\ucc98\ub7fc \uc7a5\uc18c\ub97c \uc54c\ub824 \uc8fc\ub294 \ub9d0\uc774\uc5d0\uc694.", "wrongFeedback": "\uc774\ubc88\uc5d0\ub294 \uc548\ub0b4\ud310\uc758 \uc717\uc904\uc744 \uba3c\uc800 \ubcf4\uc138\uc694. \uc717\uc904\uc5d0 \uc801\ud78c Gym\uc774 \uc7a5\uc18c\ub97c \ub098\ud0c0\ub0b4\ub294 \ub9d0\uc774\uc5d0\uc694.", "sourceTextLines": ["Gym", "Wear sports shoes"], "sceneTextLines": ["Gym", "Wear sports shoes"]}','null',2);
INSERT INTO content_stages VALUES('stage_content_student_테스트가람_ebd58e17_1778241784_3199ba2a_3','content_student_테스트가람_ebd58e17_1778241784_3199ba2a',3,'applied_problem','blank_fill','문제 2','Office 안내판을 보고, 빈칸에 들어갈 알맞은 영어 문장을 골라 넣어 봅시다.','{"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_3", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_3_audio", "assetBundle": {"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_3", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_3_audio"}, "question": "Office \uc548\ub0b4\ubb38\uc5d0\uc11c \uc544\ub798 \ubb38\uc7a5\uc744 \uc644\uc131\ud574 \ubd05\uc2dc\ub2e4.\n\nOffice \u2013 __", "sentence": "Office \u2013 __", "tiles": ["Ask here", "Be quiet"], "acceptedAnswers": [{"answer": "Ask here"}], "correctFeedback": "\uc88b\uc544\uc694. Office \u2013 Ask here\ub294 \u2018\uad50\ubb34\uc2e4\uc5d0\uc11c \uc5ec\uae30\uc5d0\uc11c \ubb3c\uc5b4\ubcf4\uc138\uc694\u2019\ub77c\ub294 \ub73b\uc774\uc5d0\uc694.", "wrongFeedback": "\uc774\ubc88\uc5d0\ub294 \ub9d0\ud48d\uc120 \uc544\uc774\ucf58\uc744 \ud568\uaed8 \ubcf4\uc138\uc694. \u2018\uc5ec\uae30\uc5d0\uc11c \ubb3c\uc5b4\ubcf4\uc138\uc694\u2019\ub77c\ub294 \ub73b\uc758 Ask here\uac00 \uc798 \uc5b4\uc6b8\ub824\uc694.", "sourceTextLines": ["Office", "Ask here"], "sceneTextLines": ["Office", "Ask here"]}','null',3);
INSERT INTO content_stages VALUES('stage_content_student_테스트가람_ebd58e17_1778241784_3199ba2a_4','content_student_테스트가람_ebd58e17_1778241784_3199ba2a',4,'realtime_practice','realtime_teach_back','설명해보기','지금까지 본 안내판을 떠올리며, ‘장소 + 해야 할 행동’이 들어간 짧은 영어 안내문을 한두 개 만들어서 소리 내어 말해 보세요.','{"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime", "audioAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime_audio"}, "situationText": "\ubcf5\ub3c4\uc5d0 \ubcf4\uc774\ub294 Library, Gym, Office \uc548\ub0b4\ud310\uc744 \ub5a0\uc62c\ub9ac\uba70, \u2018\uc7a5\uc18c + \ud574\uc57c \ud560 \ud589\ub3d9\u2019 \ubb38\uc7a5\uc744 \uc2a4\uc2a4\ub85c \ub9d0\ud574 \ubd05\uc2dc\ub2e4.", "practicePrompt": "\uc608\ub97c \ub4e4\uc5b4 \u2018Library \u2013 Be quiet\u2019\ucc98\ub7fc, \uc7a5\uc18c\uc640 \ud574\uc57c \ud560 \ud589\ub3d9\uc774 \ud568\uaed8 \ub4e4\uc5b4\uac04 \uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \ud55c \ubb38\uc7a5\uc529 \ub9d0\ud574 \ubcf4\uc138\uc694.", "sourceTextLines": ["Library \u2013 Be quiet", "Gym \u2013 Wear sports shoes", "Office \u2013 Ask here"], "sceneTextLines": ["Library", "Be quiet", "Gym", "Wear sports shoes", "Office", "Ask here"]}','{"id": "rt_spec_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a", "stageId": "stage_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\uc124\uba85\ud574\ubcf4\uae30", "situationText": "\ud559\uad50 \ubcf5\ub3c4\ub97c \uac78\uc73c\uba74\uc11c Library, Gym, Office \uc548\ub0b4\ud310\uc744 \ubcf8\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc138\uc694. \uac01 \uc7a5\uc18c\uc5d0\uc11c \ud574\uc57c \ud560 \uc77c\uc744 \uc9e7\uc740 \uc601\uc5b4 \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud574 \ubd05\ub2c8\ub2e4.", "aiRole": "\uce5c\uc808\ud558\uac8c \ud568\uaed8 \uc5f0\uc2b5\ud574 \uc8fc\ub294 \uc601\uc5b4 \uc120\uc0dd\ub2d8", "openingLine": "\ubcf5\ub3c4\uc5d0 \uc601\uc5b4 \uc548\ub0b4\ud310\uc774 \ubcf4\uc774\ub124\uc694. \uc6b0\ub9ac\uac00 \ubcf8 \uac83\ucc98\ub7fc, \ud55c \uc548\ub0b4\ubb38\uc5d0 \u2018\uc7a5\uc18c\u2019\uc640 \u2018\ud574\uc57c \ud560 \ud589\ub3d9\u2019\uc744 \ub123\uc5b4\uc11c \ud55c\ub450 \ubb38\uc7a5\uc744 \ub9d0\ud574 \ubcfc\uae4c\uc694?", "studentGoal": "Library, Gym, Office \uac19\uc740 \uc7a5\uc18c \ub2e8\uc5b4\uc640 Be quiet, Wear sports shoes, Ask here \uac19\uc740 \ud589\ub3d9 \ubb38\uc7a5\uc744 \uc9dd\uc9c0\uc5b4, \uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \uc2a4\uc2a4\ub85c \ud55c\ub450 \uac1c \ub9d0\ud574 \ubcf8\ub2e4.", "rubric": [{"id": "r1", "label": "\uc7a5\uc18c \ub2e8\uc5b4(Library, Gym, Office \ub4f1)\ub97c \ub610\ub837\ud558\uac8c \ub9d0\ud55c\ub2e4.", "required": true}, {"id": "r2", "label": "\ud574\uc57c \ud560 \ud589\ub3d9 \ubb38\uc7a5(Be quiet, Wear sports shoes, Ask here \ub4f1)\uc744 \ud568\uaed8 \ubd99\uc5ec \ub9d0\ud55c\ub2e4.", "required": true}, {"id": "r3", "label": "\ud55c \ubc88\uc5d0 \ud55c \uc548\ub0b4\ubb38\uc529 \uc9e7\uac8c \ub9d0\ud55c\ub2e4.", "required": false}, {"id": "r4", "label": "\ub73b\uc774 \uc870\uae08 \ub2ec\ub77c\ub3c4 \uc7a5\uc18c+\ud589\ub3d9 \uad6c\uc870\ub97c \uc720\uc9c0\ud55c\ub2e4.", "required": false}, {"id": "r5", "label": "\ub9c9\ud788\uba74 \uc7a0\uae50 \uc26c\uace0 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uac70\ub098, \ub2e4\uc2dc \ub9d0\ud574 \ub2ec\ub77c\uace0 \uc694\uccad\ud55c\ub2e4.", "required": false}], "allowedFeedback": ["\ud559\uc0dd\uc774 \ub9d0\ud55c \ubb38\uc7a5\uc5d0\uc11c \uc798 \ub098\uc628 \ubd80\ubd84\uc744 \uba3c\uc800 \ub9d0\ud574 \uc8fc\uace0, \ube60\uc9c4 \uc7a5\uc18c\ub098 \ud589\ub3d9 \ud45c\ud604\uc744 \ud55c \uac00\uc9c0\ub9cc \uc9da\uc5b4 \uc8fc\uba70 \ub2e4\uc2dc \ub9d0\ud574 \ubcf4\ub3c4\ub85d gently \uc81c\uc548\ud569\ub2c8\ub2e4.", "\ud559\uc0dd\uc774 \ub9c9\ud790 \ub54c\ub294 \uc608\uc2dc \ud55c \ubb38\uc7a5(Library \u2013 Be quiet \ub4f1)\uc744 \ucc9c\ucc9c\ud788 \ub2e4\uc2dc \ub4e4\ub824 \uc8fc\uace0, \ube44\uc2b7\ud55c \uad6c\uc870\ub85c \ub530\ub77c \ub9d0\ud574 \ubcf4\ub3c4\ub85d \uc720\ub3c4\ud569\ub2c8\ub2e4.", "\ubc1c\uc74c\uc774 \uc644\ubcbd\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc758\ubbf8\uac00 \uc804\ub2ec\ub418\uba74 \ucda9\ubd84\ud558\ub2e4\uace0 \uc54c\ub824 \uc8fc\uba70, \ud55c \ub2e8\uc5b4\uc529 \ub04a\uc5b4 \uc5f0\uc2b5\ud558\ub3c4\ub85d \ub3d5\uc2b5\ub2c8\ub2e4."], "forbidden": ["\uc815\ub2f5 \ubb38\uc7a5\uc744 \uadf8\ub300\ub85c \uba3c\uc800 \ub9d0\ud574 \uc8fc\uace0 \ud559\uc0dd\uc5d0\uac8c \uadf8\ub300\ub85c \ub530\ub77c \ud558\ub77c\uace0\ub9cc \uc2dc\ud0a4\uc9c0 \uc54a\uae30", "\uc5ec\ub7ec \ubb38\uc7a5\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc694\uad6c\ud558\uac70\ub098 \uc7ac\ucd09\ud574\uc11c \ube60\ub974\uac8c \ub9d0\ud558\uac8c \ud558\uc9c0 \uc54a\uae30", "\ubc1c\uc74c \uc2e4\uc218\ub098 \ub9c9\ud798\uc744 \uc9c0\uc801\ub9cc \ud558\uace0 \uad6c\uccb4\uc801\uc778 \ub2e4\uc74c \uc2dc\ub3c4\ub97c \uc548\ub0b4\ud558\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 180, "postPracticeReflection": ["\uc624\ub298 \ub0b4\uac00 \uc81c\uc77c \ub9d0\ud558\uae30 \ud3b8\ud588\ub358 \uc548\ub0b4\ubb38 \ud55c \ubb38\uc7a5\uc744 \ub5a0\uc62c\ub824 \ubcfc\uae4c\uc694?", "\uc7a5\uc18c\uc640 \ud574\uc57c \ud560 \ud589\ub3d9 \uc911\uc5d0\uc11c, \ub2e4\uc74c\uc5d0 \ub610 \uc5f0\uc2b5\ud574 \ubcf4\uace0 \uc2f6\uc740 \ubd80\ubd84\uc740 \ubb34\uc5c7\uc778\uac00\uc694? \ud55c \ub2e8\uc5b4\ub85c \ub5a0\uc62c\ub824 \ubcf4\uc138\uc694."]}',4);
