se short source lines: Library / Gym / Office / Be quiet / Wear sports shoes / Ask here / Library \u2013 Be quiet / Gym \u2013 Wear sports shoes / Office \u2013 Ask here. Avoid app UI, worksheet layout, answer panels, scoring marks, feedback bubbles, category labels, long labels, watermarks, logos, decorative generic scenes, split-screen comparison diagrams, warning/safety signs, and any visual overlay that tells the answer. The image must look like a natural scene, not an instructional diagram.", "textRenderingPolicy": "short_scene_text_allowed_no_problem_ui", "ocrPolicy": "short_scene_text_allowed_no_problem_ui", "ocrRequired": true, "sceneTextLines": ["Library", "Gym", "Office", "Be quiet", "Wear sports shoes", "Ask here", "Library \u2013 Be quiet", "Gym \u2013 Wear sports shoes", "Office \u2013 Ask here"], "promptVersion": "image_brief_v1", "negativePromptRules": ["no app UI", "no answer panels", "no scoring marks", "no feedback text", "no category labels", "no watermark"], "learningEvidence": {"primaryObject": "\ubcf5\ub3c4 \ubcbd\uc5d0 \ubd99\uc740 \uc601\uc5b4 \uc548\ub0b4\ud310", "mustBeReadableOrCountable": ["Library", "Gym", "Office", "Be quiet", "Wear sports shoes", "Ask here", "Library \u2013 Be quiet", "Gym \u2013 Wear sports shoes", "Office \u2013 Ask here"], "whyItMattersForThisStage": "\uc804\uccb4 \ud65c\ub3d9\uc758 \ubc30\uacbd\uc774 \ub418\ub294 \ud559\uad50 \ubcf5\ub3c4\uc640 \uc601\uc5b4 \uc548\ub0b4\ud310 \ubd84\uc704\uae30\ub97c \uc804\ub2ec\ud55c\ub2e4."}, "compositionPlan": {"camera": "medium-close establishing shot", "subjectPriority": "learning_object_first", "humanPresence": "small-background-context", "negativeComposition": ["portrait-first framing", "generic decorative scene", "worksheet-like composition"]}, "qaChecklist": ["scene matches stage purpose", "learning evidence is visually dominant", "no problem UI embedded", "student-safe tone"]}',NULL,'/generated/assets/students/student_테스트가람_ebd58e17/content_student_테스트가람_ebd58e17_1778241