INSERT INTO student_context_briefs VALUES('context_brief_student_테스트가람_ebd58e17_060d41a3','student_테스트가람_ebd58e17','테스트가람 학생은 짧은 지시를 이해하기, 예시 문장을 보고 따라 말하기에 강점이 관찰됩니다. 이전 수업과 관찰 기록을 보면 짧은 지시를 이해하기, 예시 문장을 보고 따라 말하기를 활용할 때 안정적입니다. 읽기 부담은 낮은 편, 선택지는 2개 안팎이 적합합니다. 주의할 흐름: 긴 글을 읽고 시작 상황에서 지원이 필요할 수 있어요, 여러 조건을 한 번에 처리 상황에서 지원이 필요할 수 있어요. 다음 자료는 예시를 먼저 보여주기, 지시를 짧게 나누기 같은 지원 방식을 유지하면서 다양한 상황에서 같은 전략을 옮겨 연습하도록 확장하면 좋습니다.','학습지원형','low',2,'["\uc9e7\uc740 \uc9c0\uc2dc\ub97c \uc774\ud574\ud568", "\uc608\uc2dc \ubb38\uc7a5\uc744 \ubcf4\uace0 \ub530\ub77c \ub9d0\ud568", "\uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\uc9c0\uc2dc\ub97c \uc9e7\uac8c \ub098\ub214", "\uc120\ud0dd\uc9c0\ub97c \uc904\uc784", "\uae30\ub2e4\ub9b4 \uc2dc\uac04\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428"]','["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694.", "\uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."]','["\uc608\uc2dc\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\uc9c0\uc2dc\ub97c \uc9e7\uac8c \ub098\ub214", "\uc120\ud0dd\uc9c0\ub97c \uc904\uc784", "\uae30\ub2e4\ub9b4 \uc2dc\uac04\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428", "\uc9e7\uc740 \uc9c0\uc2dc\ub97c \uc774\ud574\ud568", "\uc608\uc2dc \ubb38\uc7a5\uc744 \ubcf4\uace0 \ub530\ub77c \ub9d0\ud568"]','["\uae34 \uae00\uc744 \uc77d\uace0 \uc2dc\uc791, \uc5ec\ub7ec \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \ucc98\ub9ac\uc5d0\uc11c \ud575\uc2ec \ub2e8\uc11c\ub97c \uba3c\uc800 \ud655\uc778\ud558\uace0 \uc9e7\uc740 \ub2e8\uacc4\ub85c \uac1c\ub150\uc744 \uc124\uba85\ud558\uae30"]','2026-05-08T11:53:44.929379+00:00',1,'dirty','{"trigger": "manual_refresh", "reportCount": 0, "lastDirtySource": {"trigger": "new_content_saved", "contentId": "content_student_\ud14c\uc2a4\ud2b8\uac00\ub78c_ebd58e17_1778241784_3199ba2a", "status": "teacher_review"}, "dirtySources